package de.nevergate.fahrzeuge;
import java.util.*;
import net.minecraft.core.BlockPos;
import net.minecraft.gametest.framework.*;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.*;
import net.minecraftforge.gametest.GameTestHolder;
@GameTestHolder(value=NgFahrzeuge.MOD_ID,namespace=NgFahrzeuge.MOD_ID)
public final class Dev11GameTests {
 private static NgCityEntity car(GameTestHelper h,VehicleSpec s){var c=VehicleContent.type(s).create(h.getLevel());var b=h.absolutePos(new BlockPos(1,1,1));c.setPos(b.getX()+.5,h.getLevel().getMaxBuildHeight()-12,b.getZ()+.5);c.setNoGravity(true);h.getLevel().addFreshEntity(c);return c;}
 private static Player player(GameTestHelper h,NgCityEntity c){var p=h.makeMockPlayer();p.setUUID(UUID.randomUUID());p.getAbilities().mayBuild=true;p.getAbilities().instabuild=false;p.setPos(c.position());return p;}
 private static Player owner(GameTestHelper h,NgCityEntity c){var p=player(h,c);c.equipment.claim(p);return p;}
 @GameTest(template="forge:empty3x3x3",timeoutTicks=30)
 public static void busThirteenDistinctSeatsAndOneVehicleIdentity(GameTestHelper h){var c=car(h,VehicleSpec.BUS);var p=owner(h,c);p.startRiding(c);for(int i=1;i<13;i++)h.assertTrue(player(h,c).startRiding(c),"Bus seat rejected");h.assertFalse(player(h,c).startRiding(c),"Bus over capacity");h.assertTrue(c.getPassengers().stream().map(c::getPassengerRidingPosition).distinct().count()==13,"Shared bus seats");var v=VehicleSnapshot.of(c).orElseThrow();h.assertTrue(v.driver().equals(p.getUUID())&&v.id().equals(c.getUUID())&&c.getTags().contains("ng_bus")&&Math.abs(v.bounds().getZsize()-8)<.001,"Bus identity/bounds/tag");c.discard();h.succeed();}
 @GameTest(template="forge:empty3x3x3",timeoutTicks=30)
 public static void busDoorsIndependentAndStopRequestPassengerOnly(GameTestHelper h){var c=car(h,VehicleSpec.BUS);var p=owner(h,c);p.startRiding(c);var rider=player(h,c);rider.startRiding(c);h.assertFalse(c.applyAction(p,19),"Driver requested own stop");h.assertTrue(c.applyAction(rider,19)&&c.systems.expansion.stopRequested(),"Passenger stop request missing");h.assertFalse(c.applyAction(rider,8),"Passenger opened driver door");c.applyAction(p,2);h.assertTrue(c.engineRunning(),"Bus engine not started");h.assertTrue(c.applyAction(p,8)&&c.systems.doors()==1&&!c.systems.expansion.stopRequested(),"Front door/request reset");h.assertTrue(c.applyAction(p,9)&&c.systems.doors()==3,"Rear door not independent");c.applyAction(p,8);h.assertTrue(c.systems.doors()==2,"Front closure closed rear");c.discard();h.succeed();}
 @GameTest(template="forge:empty3x3x3",timeoutTicks=30)
 public static void passengerActionsRejectStrangersAndDriving(GameTestHelper h){var c=car(h,VehicleSpec.BUS);var p=owner(h,c);p.startRiding(c);var rider=player(h,c);rider.startRiding(c);var stranger=player(h,c);h.assertFalse(c.applyAction(stranger,19)||c.applyAction(stranger,20)||c.acceptInput(rider,1)||c.applyAction(rider,2)||c.applyAction(rider,23),"Passenger/stranger authority leak");c.discard();h.succeed();}
 @GameTest(template="forge:empty3x3x3",timeoutTicks=30)
 public static void routeValidationAndPackedPersistence(GameTestHelper h){var c=car(h,VehicleSpec.BUS);var p=owner(h,c);h.assertTrue(c.systems.expansion.setRoute(p,"N42","NeverGate ZOB"),"Route rejected");h.assertFalse(c.systems.expansion.setRoute(p,"123456789","x")||c.systems.expansion.setRoute(p,"A","a\nb"),"Unsafe route accepted");var copy=VehicleContent.NG_BUS.get().create(h.getLevel());copy.loadEquipment(c.getPickResult().getTag());h.assertTrue(copy.systems.expansion.route().equals("N42")&&copy.systems.expansion.destination().equals("NeverGate ZOB"),"Route lost on packing");c.discard();h.succeed();}
 @GameTest(template="forge:empty3x3x3",timeoutTicks=30)
 public static void motorcycleHasTwoInlineSeatsAndRejectsThird(GameTestHelper h){var c=car(h,VehicleSpec.MOTORCYCLE);var p=owner(h,c);p.startRiding(c);var rider=player(h,c);h.assertTrue(rider.startRiding(c)&&c.getPassengerRidingPosition(p).distanceTo(c.getPassengerRidingPosition(rider))>.5,"Sozius seat missing");h.assertFalse(player(h,c).startRiding(c),"Third motorcycle rider");h.assertFalse(c.systems.couple(p),"Motorcycle coupled trailer");c.discard();h.succeed();}
 @GameTest(template="forge:empty3x3x3",timeoutTicks=30)
 public static void sideStandPreventsStartAndBoardingRaisesStand(GameTestHelper h){var c=car(h,VehicleSpec.MOTORCYCLE);var p=owner(h,c);c.systems.expansion.tick();h.assertTrue(c.systems.expansion.stand()&&!c.systems.canRun(),"Stand did not secure bike");c.interact(p,net.minecraft.world.InteractionHand.MAIN_HAND);h.assertFalse(c.systems.expansion.stand(),"Boarding did not raise stand");h.assertTrue(c.applyAction(p,22)&&!c.systems.canRun(),"Stand action missing");c.applyAction(p,22);h.assertTrue(c.applyAction(p,2)&&c.engineRunning(),"Raised stand did not permit engine");h.assertFalse(c.applyAction(p,22),"Stand lowered under running engine");c.discard();h.succeed();}
 @GameTest(template="forge:empty3x3x3",timeoutTicks=30)
 public static void motorcycleAccelerationAndBusSpeedDiffer(GameTestHelper h){var c=car(h,VehicleSpec.CITY);var bike=car(h,VehicleSpec.MOTORCYCLE);var bus=car(h,VehicleSpec.BUS);float city=c.systems.speed(.1F,1,false,false),b=bike.systems.speed(.1F,1,false,false);h.assertTrue(b>city&&bike.systems.speed(.56F,1,false,false)>.56F,"Bike acceleration/cap unchanged");h.assertTrue(bus.systems.speed(.4F,1,false,false)<=.34001,"Bus speed not limited");c.discard();bike.discard();bus.discard();h.succeed();}
 @GameTest(template="forge:empty3x3x3",timeoutTicks=30)
 public static void pickupTailgateAndLoadSurvivePacking(GameTestHelper h){var c=car(h,VehicleSpec.PICKUP);var p=owner(h,c);h.assertTrue(c.systems.action(p,9)&&c.systems.doors()==2,"Pickup tailgate missing");c.equipment.cargo.setItem(26,new ItemStack(Items.DIAMOND,7));var copy=VehicleContent.NG_PICKUP.get().create(h.getLevel());copy.loadEquipment(c.getPickResult().getTag());h.assertTrue(copy.systems.doors()==2&&copy.equipment.cargo.getItem(26).getCount()==7,"Pickup packing lost load/gate");c.discard();h.succeed();}
 @GameTest(template="forge:empty3x3x3",timeoutTicks=30)
 public static void visualLoadCountsDoNotBroadcastPrivateStacks(GameTestHelper h){var c=car(h,VehicleSpec.PICKUP);for(int i=0;i<11;i++)c.equipment.cargo.setItem(i,new ItemStack(Items.DIAMOND));for(int i=0;i<6;i++)c.systems.upgrades.roof.setItem(i,new ItemStack(Items.GOLD_INGOT));c.systems.sync();h.assertTrue(c.systemTag().getInt("CargoCrates")==3&&c.systemTag().getInt("RoofCrates")==2,"Load geometry count wrong");h.assertFalse(c.systemTag().contains("VehicleCargo")||c.systemTag().contains("RoofCargo"),"Private cargo broadcast");c.equipment.cargo.clearContent();c.systems.sync();h.assertTrue(c.systemTag().getInt("CargoCrates")==0,"Empty load remained visible");c.discard();h.succeed();}
 @GameTest(template="forge:empty3x3x3",timeoutTicks=30)
 public static void blinkersCancelAfterTurnButHazardsRemain(GameTestHelper h){var c=car(h,VehicleSpec.CITY);var p=owner(h,c);p.startRiding(c);c.applyAction(p,4);c.setYRot(25);c.yRotO=22;c.systems.expansion.tick();c.applyAction(p,2);c.applyAction(p,0);c.acceptInput(p,1);c.tick();for(int i=0;i<5;i++){c.acceptInput(p,1);c.tick();}h.assertTrue(c.signal()==0,"Indicator did not return after turn");c.applyAction(p,5);c.systems.expansion.tick();h.assertTrue(c.signal()==3,"Hazards auto-cancelled");c.discard();h.succeed();}
 @GameTest(template="forge:empty3x3x3",timeoutTicks=30)
 public static void seatAdjustmentMovesDriverAndPersists(GameTestHelper h){var c=car(h,VehicleSpec.FAMILY);var p=owner(h,c);p.startRiding(c);var before=c.getPassengerRidingPosition(p);h.assertTrue(c.systems.expansion.setSeat(p,5,4),"Seat edit failed");var after=c.getPassengerRidingPosition(p);h.assertTrue(Math.abs(after.y-before.y-.1)<.001&&Math.abs(after.z-before.z-.2)<.001,"Driver viewpoint not moved");var copy=VehicleContent.NG_FAMILY.get().create(h.getLevel());copy.loadEquipment(c.getPickResult().getTag());h.assertTrue(copy.systems.expansion.seatForward()==5&&copy.systems.expansion.seatHeight()==4,"Seat not saved");h.assertFalse(c.systems.expansion.setSeat(p,6,0),"Out of bounds seat");c.discard();h.succeed();}
 @GameTest(template="forge:empty3x3x3",timeoutTicks=30)
 public static void beltsAreIndividualAndClearAfterExit(GameTestHelper h){var c=car(h,VehicleSpec.FAMILY);var p=owner(h,c);p.startRiding(c);var q=player(h,c);q.startRiding(c);h.assertTrue(c.applyAction(p,20)&&c.applyAction(q,20)&&Integer.bitCount(c.systems.expansion.beltMask())==2,"Seatbelt state not individual");q.stopRiding();c.systems.expansion.reconcileBelts();h.assertTrue(Integer.bitCount(c.systems.expansion.beltMask())==1&&!c.systems.expansion.belted(q),"Exited belt not cleared");q.startRiding(c);h.assertFalse(c.systems.expansion.belted(q),"New seat automatically belted");c.discard();h.succeed();}
 @GameTest(template="forge:empty3x3x3",timeoutTicks=30)
 public static void paintConsumesExactMaterialsAndRejectsMissingIron(GameTestHelper h){var c=car(h,VehicleSpec.PICKUP);var p=owner(h,c);var dye=new ItemStack(Items.RED_DYE,2);h.assertFalse(VehiclePaintBlock.paint(c,p,dye)||dye.getCount()!=2,"Unpaid paint consumed dye");p.getInventory().setItem(8,new ItemStack(Items.IRON_INGOT,2));h.assertTrue(VehiclePaintBlock.paint(c,p,dye)&&dye.getCount()==1&&p.getInventory().countItem(Items.IRON_INGOT)==1&&c.color()==14,"Paint transaction not exact");h.assertFalse(VehiclePaintBlock.paint(c,p,dye)||dye.getCount()!=1,"Same colour charged again");c.discard();h.succeed();}
 @GameTest(template="forge:empty3x3x3",timeoutTicks=30)
 public static void paintRejectsForeignOrOccupiedVehicle(GameTestHelper h){var c=car(h,VehicleSpec.CITY);var p=owner(h,c);var q=player(h,c);q.getInventory().setItem(8,new ItemStack(Items.IRON_INGOT));var dye=new ItemStack(Items.RED_DYE);h.assertFalse(VehiclePaintBlock.paint(c,q,dye),"Foreign car painted");p.startRiding(c);p.getInventory().setItem(8,new ItemStack(Items.IRON_INGOT));h.assertFalse(VehiclePaintBlock.paint(c,p,dye),"Occupied car painted");c.discard();h.succeed();}
 @GameTest(template="forge:empty3x3x3",timeoutTicks=30)
 public static void separateLightModesFogAndPersistence(GameTestHelper h){var c=car(h,VehicleSpec.CITY);var p=owner(h,c);p.startRiding(c);c.applyAction(p,1);h.assertTrue(c.systems.expansion.lightMode()==1&&c.lightsOn(),"Parking lamps missing");h.assertFalse(c.applyAction(p,21),"High beam enabled without dipped lamps");c.applyAction(p,1);h.assertTrue(c.systems.expansion.lightMode()==2&&c.applyAction(p,21)&&c.systems.expansion.lightMode()==3,"High beam missing");h.assertTrue(c.applyAction(p,23)&&c.systems.expansion.fog(),"Fog lamps missing");var copy=VehicleContent.NG_CITY.get().create(h.getLevel());copy.loadEquipment(c.getPickResult().getTag());h.assertTrue(copy.systems.expansion.fog()&&copy.systems.expansion.lightMode()==3,"Lamp save lost");c.applyAction(p,1);h.assertTrue(!c.lightsOn()&&c.systems.expansion.lightMode()==0,"Lamp cycle did not turn off");c.discard();h.succeed();}
 @GameTest(template="forge:empty3x3x3",timeoutTicks=30)
 public static void directoryOnlyReturnsOwnerAndTracksTransfer(GameTestHelper h){var c=car(h,VehicleSpec.PICKUP);var p=owner(h,c);var q=player(h,c);var d=VehicleDirectoryData.get(h.getLevel());h.assertTrue(d.own(p.getUUID()).stream().anyMatch(t->t.getUUID("Id").equals(c.getUUID()))&&d.own(q.getUUID()).isEmpty(),"Owner filter failed");h.assertTrue(c.equipment.changeOwner(p,q.getUUID()),"Transfer failed");h.assertFalse(d.own(p.getUUID()).stream().anyMatch(t->t.getUUID("Id").equals(c.getUUID())),"Previous owner can locate transferred car");c.discard();h.assertFalse(d.own(q.getUUID()).stream().anyMatch(t->t.getUUID("Id").equals(c.getUUID())),"Sold/packed instance retained");h.succeed();}
 @GameTest(template="forge:empty3x3x3",timeoutTicks=30)
 public static void directorySavedDataAndGarageStatusPersist(GameTestHelper h){var c=car(h,VehicleSpec.PICKUP);var p=owner(h,c);c.setCustomName(net.minecraft.network.chat.Component.literal("Mein Pickup"));VehicleDirectoryData.update(c);var saved=VehicleDirectoryData.get(h.getLevel()).save(new CompoundTag());var copy=VehicleDirectoryData.load(saved);var row=copy.own(p.getUUID()).get(0);h.assertTrue(row.getString("Name").equals("Mein Pickup")&&row.getDouble("X")==c.getX(),"Directory last observation lost");h.assertTrue(VehicleGarageData.get(h.getLevel()).store(c,p),"Garage store failed");h.assertTrue(VehicleDirectoryData.get(h.getLevel()).own(p.getUUID()).get(0).getBoolean("Stored"),"Stored car absent from overview");h.succeed();}
 @GameTest(template="forge:empty3x3x3",timeoutTicks=30)
 public static void allNewModelsAvailableAtDealerAndWorkbench(GameTestHelper h){for(var s:new VehicleSpec[]{VehicleSpec.BUS,VehicleSpec.MOTORCYCLE,VehicleSpec.PICKUP}){var c=car(h,s);var p=owner(h,c);p.getAbilities().instabuild=true;h.assertTrue(VehicleAssembly.assemble(p,s)&&p.getInventory().countItem(VehicleContent.item(s))==1,"Workbench missing new type");h.assertTrue(VehicleDealerConfig.buy(p,s)&&p.getInventory().countItem(VehicleContent.item(s))==2,"Dealer missing new type");c.discard();}h.succeed();}
 @GameTest(template="forge:empty3x3x3",timeoutTicks=30)
 public static void snapshotSeparatesOwnerFromForeignDriverAndRejectsRemovedTarget(GameTestHelper h){var c=car(h,VehicleSpec.BUS);var p=owner(h,c);var q=player(h,c);q.startRiding(c);var v=VehicleSnapshot.of(c).orElseThrow();h.assertTrue(v.owner().equals(p.getUUID())&&v.driver().equals(q.getUUID())&&!v.owner().equals(v.driver()),"Owner and driver conflated");c.discard();h.assertTrue(VehicleSnapshot.of(c).isEmpty()&&VehicleSnapshot.of(null).isEmpty(),"Removed target reported as current");h.succeed();}
 @GameTest(template="forge:empty3x3x3",timeoutTicks=30)
 public static void malformedExpansionStateIsBoundedAndBeltsNotRestored(GameTestHelper h){var c=car(h,VehicleSpec.FAMILY);var p=owner(h,c);p.startRiding(c);c.applyAction(p,20);var t=new CompoundTag();c.systems.save(t);t.putInt("SeatForward",999);t.putInt("SeatHeight",-999);t.putInt("LightMode",999);t.putString("Route","bad\nroute");t.putString("Destination","x".repeat(33));c.systems.load(t);h.assertTrue(c.systems.expansion.seatForward()==5&&c.systems.expansion.seatHeight()==-4&&c.systems.expansion.lightMode()==3&&c.systems.expansion.route().isEmpty()&&c.systems.expansion.destination().isEmpty()&&c.systems.expansion.beltMask()==0,"Malformed state or old occupants restored");c.discard();h.succeed();}
}
